export const getAvailablePhoneNumberBlocksRoute = createRoute({
  method: 'get',
  path: '/available_phone_number_blocks',
  tags: ['Number Search'],
  summary: 'List available phone number blocks',
  operationId: 'listAvailablePhoneNumberBlocks',
  request: {
    query: z.object({
      'filter[phone_number][starts_with]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter number blocks that start with a pattern (meant to be used after `national_destination_code` filter has been set).',
            in: 'query',
            name: 'filter[phone_number][starts_with]',
            schema: { example: '201', type: 'string' },
            required: false,
          },
          example: '201',
        }),
      'filter[phone_number][ends_with]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter numbers ending with a pattern.',
            in: 'query',
            name: 'filter[phone_number][ends_with]',
            schema: { example: '8000', type: 'string' },
            required: false,
          },
          example: '8000',
        }),
      'filter[phone_number][contains]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter numbers containing a pattern.',
            in: 'query',
            name: 'filter[phone_number][contains]',
            schema: { example: '456', type: 'string' },
            required: false,
          },
          example: '456',
        }),
      'filter[locality]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter phone numbers by city.',
            examples: {
              AU: { value: 'Canberra' },
              CA: { value: 'Toronto' },
              US: { value: 'Chicago' },
            },
            in: 'query',
            name: 'filter[locality]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[administrative_area]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter phone numbers by US state/CA province.',
            in: 'query',
            name: 'filter[administrative_area]',
            schema: { example: 'IL', type: 'string' },
            required: false,
          },
          example: 'IL',
        }),
      'filter[country_code]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter phone numbers by ISO alpha-2 country code.',
            in: 'query',
            name: 'filter[country_code]',
            schema: { example: 'US', type: 'string' },
            required: false,
          },
          example: 'US',
        }),
      'filter[national_destination_code]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter by the national destination code of the number. This filter is only applicable to North American numbers.',
            examples: { AU: { value: '0251' }, CA: { value: '437' }, US: { value: '312' } },
            in: 'query',
            name: 'filter[national_destination_code]',
            schema: { type: 'string' },
            required: false,
          },
        }),
      'filter[rate_center]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter phone numbers by NANP rate center. This filter is only applicable to North American numbers.',
            in: 'query',
            name: 'filter[rate_center]',
            schema: { example: 'CHICAGO HEIGHTS', type: 'string' },
            required: false,
          },
          example: 'CHICAGO HEIGHTS',
        }),
      'filter[number_type]': z
        .literal('toll-free')
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter phone numbers by number type.',
            in: 'query',
            name: 'filter[number_type]',
            schema: { enum: ['toll-free'], example: 'toll-free', type: 'string' },
            required: false,
          },
          example: 'toll-free',
        }),
      'filter[features]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.enum(['sms', 'mms', 'voice', 'fax', 'emergency'])),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter if the phone number should be used for voice, fax, mms, sms, emergency.',
            in: 'query',
            name: 'filter[features]',
            schema: {
              example: 'voice,sms',
              items: { enum: ['sms', 'mms', 'voice', 'fax', 'emergency'], type: 'string' },
              type: 'array',
            },
            required: false,
          },
          example: 'voice,sms',
        }),
      'filter[minimum_block_size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter number blocks by minimum blocks size',
            in: 'query',
            name: 'filter[minimum_block_size]',
            schema: { example: 100, type: 'integer' },
            required: false,
          },
          example: 100,
        }),
      'filter[limit]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Limits the number of results.',
            in: 'query',
            name: 'filter[limit]',
            schema: { example: 100, type: 'integer' },
            required: false,
          },
          example: 100,
        }),
    }),
  },
  responses: {
    200: ListAvailablePhoneNumbersBlockResponseResponse,
    default: GenericErrorResponseResponse,
  },
})

