export const getDetailRecordsRoute = createRoute({
  method: 'get',
  path: '/detail_records',
  tags: ['Detail Records'],
  summary: 'Search detail records',
  description: 'Search for any detail record across the Telnyx Platform',
  operationId: 'DetailRecordsSearch',
  request: {
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const open: string[] = ['filter']
        const taken: string[] = [
          'filter[record_type]',
          'filter[date_range]',
          'page[number]',
          'page[size]',
          'sort',
        ]
        for (const [key, item] of Object.entries(val)) {
          if (!taken.includes(key)) {
            for (const owner of open) {
              group(owner)[key] = item
            }
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          'filter[record_type]': z
            .string()
            .openapi({
              param: {
                description: 'Filter by the given record type',
                examples: {
                  'filter[record_type]=messaging': {
                    summary: 'Searches for messaging detail records',
                    value: 'messaging',
                  },
                },
                in: 'query',
                name: 'filter[record_type]',
                required: true,
                schema: { type: 'string' },
              },
            }),
          'filter[date_range]': z
            .string()
            .exactOptional()
            .openapi({
              param: {
                description: 'Filter by the given user-friendly date range',
                examples: {
                  'filter[date_range]=last_3_days': {
                    summary:
                      'Searches for records with timestamp starting at `00:00:00` since 3 days ago',
                    value: 'last_3_days',
                  },
                  'filter[date_range]=today': {
                    summary:
                      'Searches for records with timestamp starting at `00:00:00` of the current day',
                    value: 'today',
                  },
                },
                in: 'query',
                name: 'filter[date_range]',
                required: false,
                schema: { type: 'string' },
              },
            }),
          filter: z
            .looseObject({})
            .exactOptional()
            .openapi({
              param: {
                description: 'Filter records',
                examples: {
                  'filter[cld][contains]=456': {
                    summary:
                      'Searches for records which have the property `cld` containing the pattern `456`',
                    value: '456',
                  },
                  'filter[cld][ends_with]=789': {
                    summary:
                      'Searches for records which have the property `cld` ending with the suffix `789`',
                    value: '789',
                  },
                  'filter[cld][starts_with]=123': {
                    summary:
                      'Searches for records which have the property `cld` starting with the prefix `123`',
                    value: '123',
                  },
                  'filter[created_at][gte]=2021-06-22': {
                    summary: 'Searches for records with `created_at` starting at `2021-06-22`',
                    value: '2021-06-22',
                  },
                  'filter[created_at][lt]=2021-06-23': {
                    summary: 'Searches for records with `created_at` ending at `2021-06-22`',
                    value: '2021-06-23',
                  },
                  'filter[direction]=inbound': {
                    summary:
                      'Searches for records which have the property `direction` equal to `inbound`',
                    value: 'inbound',
                  },
                },
                in: 'query',
                name: 'filter',
                required: false,
                schema: { additionalProperties: true, type: 'object' },
              },
            }),
          'page[number]': z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int32().min(1),
            )
            .default(1)
            .exactOptional()
            .openapi({
              param: {
                description: 'Page number',
                in: 'query',
                name: 'page[number]',
                schema: { default: 1, format: 'int32', minimum: 1, type: 'integer' },
                required: false,
              },
            }),
          'page[size]': z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int32().min(1).max(50),
            )
            .default(20)
            .exactOptional()
            .openapi({
              param: {
                description: 'Page size',
                in: 'query',
                name: 'page[size]',
                schema: { default: 20, format: 'int32', maximum: 50, minimum: 1, type: 'integer' },
                required: false,
              },
            }),
          sort: z
            .preprocess(
              (val) => (val === undefined || Array.isArray(val) ? val : [val]),
              z.array(z.string()),
            )
            .exactOptional()
            .openapi({
              param: {
                description: 'Specifies the sort order for results',
                examples: {
                  'sort=-created_at': {
                    summary:
                      'Sorts search results using the `created_at` date-time in descending order',
                    value: 'created_at',
                  },
                  'sort=created_at': {
                    summary:
                      'Sorts search results using the `created_at` date-time in ascending order',
                    value: 'created_at',
                  },
                },
                in: 'query',
                name: 'sort',
                schema: { items: { type: 'string' }, type: 'array' },
                required: false,
              },
            }),
        }),
      ),
  },
  responses: {
    200: {
      description: 'Successful',
      content: { 'application/json': { schema: DetailRecordsSearchResponseSchema } },
    },
  },
  security: [{ bearerAuth: [] }],
})

