export const postFaxesRoute = createRoute({
  method: 'post',
  path: '/faxes',
  tags: ['Programmable Fax Commands'],
  summary: 'Send a fax',
  operationId: 'SendFax',
  request: {
    body: {
      description: 'Send fax request',
      content: {
        'application/json': { schema: SendFaxRequestSchema },
        'multipart/form-data': {
          schema: z
            .object({
              connection_id: z
                .string()
                .openapi({
                  description: 'The connection ID to send the fax with.',
                  example: '234423',
                }),
              contents: z
                .file()
                .openapi({
                  type: 'string',
                  format: 'binary',
                  description: 'The file you want to upload. The maximum allowed size is 20 MB.',
                }),
              from: z
                .string()
                .openapi({
                  description: 'The phone number, in E.164 format, the fax will be sent from.',
                  example: '+13125790015',
                }),
              quality: z
                .string()
                .default('high')
                .exactOptional()
                .openapi({
                  description: 'The quality of the fax. Can be normal, high, very_high.',
                  example: 'high',
                }),
              store_media: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({ description: 'Should fax media be stored on temporary URL.' }),
              to: z
                .string()
                .openapi({
                  description:
                    'The phone number, in E.164 format, the fax will be sent to or SIP URI.',
                  example: '+13127367276',
                }),
            })
            .openapi({
              required: ['connection_id', 'contents', 'from', 'to'],
              title: 'Send fax multipart request',
            }),
        },
      },
      required: true,
    },
  },
  responses: { 202: SendFaxResponseResponse, default: GenericErrorResponseResponse },
  callbacks: {
    'fax.delivered': {
      '{$response.body#/data/webhook_url}': {
        post: {
          requestBody: {
            content: { 'application/json': { schema: FaxDeliveredSchema } },
            required: true,
          },
          responses: {
            200: {
              description:
                'The server must return an HTTP 200, otherwise we will reattempt delivery at the failover webhook URL.',
            },
          },
        },
      },
    },
    'fax.failed': {
      '{$response.body#/data/webhook_url}': {
        post: {
          requestBody: {
            content: { 'application/json': { schema: FaxFailedSchema } },
            required: true,
          },
          responses: {
            200: {
              description:
                'The server must return an HTTP 200, otherwise we will reattempt delivery at the failover webhook URL.',
            },
          },
        },
      },
    },
    'fax.media.processed': {
      '{$response.body#/data/webhook_url}': {
        post: {
          requestBody: {
            content: { 'application/json': { schema: FaxMediaProcessedSchema } },
            required: true,
          },
          responses: {
            200: {
              description:
                'The server must return an HTTP 200, otherwise we will reattempt delivery at the failover webhook URL.',
            },
          },
        },
      },
    },
    'fax.queued': {
      '{$response.body#/data/webhook_url}': {
        post: {
          requestBody: {
            content: { 'application/json': { schema: FaxQueuedSchema } },
            required: true,
          },
          responses: {
            200: {
              description:
                'The server must return an HTTP 200, otherwise we will reattempt delivery at the failover webhook URL.',
            },
          },
        },
      },
    },
    'fax.sending.started': {
      '{$response.body#/data/webhook_url}': {
        post: {
          requestBody: {
            content: { 'application/json': { schema: FaxSendingStartedSchema } },
            required: true,
          },
          responses: {
            200: {
              description:
                'The server must return an HTTP 200, otherwise we will reattempt delivery at the failover webhook URL.',
            },
          },
        },
      },
    },
  },
})

