export const getNumberBlockOrdersRoute = createRoute({
  method: 'get',
  path: '/number_block_orders',
  tags: ['Number Block Orders'],
  summary: 'List number block orders',
  description: 'Get a paginated list of number block orders.',
  operationId: 'listNumberBlockOrders',
  request: {
    query: z.object({
      'filter[status]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter number block orders by status.',
            in: 'query',
            name: 'filter[status]',
            schema: { example: 'pending', type: 'string' },
            required: false,
          },
          example: 'pending',
        }),
      'filter[created_at][gt]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter number block orders later than this value.',
            in: 'query',
            name: 'filter[created_at][gt]',
            schema: { example: '2018-01-01T00:00:00.000000Z', type: 'string' },
            required: false,
          },
          example: '2018-01-01T00:00:00.000000Z',
        }),
      'filter[created_at][lt]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter number block orders earlier than this value.',
            in: 'query',
            name: 'filter[created_at][lt]',
            schema: { example: '2018-01-01T00:00:00.000000Z', type: 'string' },
            required: false,
          },
          example: '2018-01-01T00:00:00.000000Z',
        }),
      'filter[phone_numbers.starting_number]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter number block  orders having these phone numbers.',
            in: 'query',
            name: 'filter[phone_numbers.starting_number]',
            schema: { example: '+19705555000', type: 'string' },
            required: false,
          },
          example: '+19705555000',
        }),
      'page[number]': PageNumberParamsSchema,
      'page[size]': PageSizeParamsSchema,
    }),
  },
  responses: { 200: ListNumberBlockOrdersResponseResponse, default: GenericErrorResponseResponse },
})

export const postNumberBlockOrdersRoute = createRoute({
  method: 'post',
  path: '/number_block_orders',
  tags: ['Number Block Orders'],
  summary: 'Create a number block order',
  description: 'Creates a phone number block order.',
  operationId: 'createNumberBlockOrder',
  request: {
    body: {
      content: { 'application/json': { schema: CreateNumberBlockOrderRequestSchema } },
      required: true,
    },
  },
  responses: { 200: NumberBlockOrderResponseResponse, default: GenericErrorResponseResponse },
  callbacks: {
    numberOrderStatusUpdate: {
      '{$request.body#/webhook_url}': {
        post: {
          requestBody: {
            content: { 'application/json': { schema: NumberOrderBlockEventSchema } },
            required: true,
          },
          responses: {
            200: {
              description:
                'The server must return a HTTP 200, otherwise we will reattempt to deliver the webhook to the failover URL.',
            },
          },
        },
      },
    },
  },
})

