export const getReportsBatchMdrReportsRoute = createRoute({
  method: 'get',
  path: '/reports/batch_mdr_reports',
  tags: ['MDR Detail Reports'],
  description:
    'Fetch all previous requests for messaging detail reports. Messaging detail reports are reports for pulling all messaging records. ',
  operationId: 'getCdrRequests',
  request: {
    query: z.object({
      'page[number]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number',
            in: 'query',
            name: 'page[number]',
            schema: { default: 1, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      'page[size]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            description: 'Size of the page',
            in: 'query',
            name: 'page[size]',
            schema: { default: 20, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful',
      content: { 'application/json': { schema: MdrGetDetailReportResponseSchema } },
    },
  },
  security: [{ bearerAuth: [] }],
})

