export const getSimCardsRoute = createRoute({
  method: 'get',
  path: '/sim_cards',
  tags: ['SIM Cards'],
  summary: 'Get all SIM cards',
  description: 'Get all SIM cards belonging to the user that match the given filters.',
  operationId: 'SimCardsGet',
  request: {
    query: z.object({
      'page[number]': PageNumberParamsSchema,
      'page[size]': PageSizeParamsSchema,
      include_sim_card_group: IncludeSIMCardGroupParamsSchema,
      'filter[sim_card_group_id]': FilterSIMCardGroupIdParamsSchema,
      'filter[tags]': z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              "A list of SIM card tags to filter on.<br/><br/>\nIf the SIM card contains <b><i>all</i></b> of the given <code>tags</code> they will be found.<br/><br/>\nFor example, if the SIM cards have the following tags: <ul>\n  <li><code>['customers', 'staff', 'test']</code>\n  <li><code>['test']</code></li>\n  <li><code>['customers']</code></li>\n</ul>\nSearching for <code>['customers', 'test']</code> returns only the first because it's the only one with both tags.<br/> Searching for <code>test</code> returns the first two SIMs, because both of them have such tag.<br/> Searching for <code>customers</code> returns the first and last SIMs.<br/>\n",
            in: 'query',
            name: 'filter[tags]',
            required: false,
            schema: {
              example: ['personal', 'customers', 'active-customers'],
              items: { type: 'string' },
              type: 'array',
            },
          },
          example: ['personal', 'customers', 'active-customers'],
        }),
      'filter[iccid]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: "A search string to partially match for the SIM card's ICCID.",
            in: 'query',
            name: 'filter[iccid]',
            required: false,
            schema: { example: '89310410106543789301', type: 'string' },
          },
          example: '89310410106543789301',
        }),
    }),
  },
  responses: { 200: SearchSimCardsResponseResponse, default: GenericErrorResponseResponse },
})

