export const getSubNumberOrdersRoute = createRoute({
  method: 'get',
  path: '/sub_number_orders',
  tags: ['Number Orders'],
  summary: 'List sub number orders',
  description: 'Get a paginated list of sub number orders.',
  operationId: 'listSubNumberOrders',
  request: {
    query: z.object({
      'filter[user_id]': z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            description: 'User ID of the user who owns the sub number order',
            in: 'query',
            name: 'filter[user_id]',
            schema: {
              example: 'd70873cd-7c98-401a-81b6-b1ae08246995',
              format: 'uuid',
              type: 'string',
            },
            required: false,
          },
          example: 'd70873cd-7c98-401a-81b6-b1ae08246995',
        }),
      'filter[order_request_id]': z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            description: 'ID of the number order the sub number order belongs to',
            in: 'query',
            name: 'filter[order_request_id]',
            schema: {
              example: '12ade33a-21c0-473b-b055-b3c836e1c293',
              format: 'uuid',
              type: 'string',
            },
            required: false,
          },
          example: '12ade33a-21c0-473b-b055-b3c836e1c293',
        }),
      'filter[country_code]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'ISO alpha-2 country code.',
            in: 'query',
            name: 'filter[country_code]',
            schema: { example: 'US', type: 'string' },
            required: false,
          },
          example: 'US',
        }),
      'filter[phone_number_type]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Phone Number Type',
            in: 'query',
            name: 'filter[phone_number_type]',
            schema: { example: 'local', type: 'string' },
            required: false,
          },
          example: 'local',
        }),
      'filter[phone_numbers_count]': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Amount of numbers in the sub number order',
            in: 'query',
            name: 'filter[phone_numbers_count]',
            schema: { example: 1, type: 'integer' },
            required: false,
          },
          example: 1,
        }),
    }),
  },
  responses: { 200: ListSubNumberOrdersResponseResponse, default: GenericErrorResponseResponse },
})

