export const getWebhookDeliveriesRoute = createRoute({
  method: 'get',
  path: '/webhook_deliveries',
  tags: ['Webhooks'],
  summary: 'List webhook deliveries',
  description: 'Lists webhook_deliveries for the authenticated user',
  operationId: 'getWebhookDeliveries',
  request: {
    query: z.object({
      'filter[status][eq]': z
        .enum(['delivered', 'failed'])
        .exactOptional()
        .openapi({
          param: {
            description: 'Return only webhook_deliveries matching the given `status`',
            in: 'query',
            name: 'filter[status][eq]',
            required: false,
            schema: { enum: ['delivered', 'failed'], example: 'delivered', type: 'string' },
          },
          example: 'delivered',
        }),
      'filter[webhook][contains]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only webhook deliveries whose `webhook` component contains the given text',
            in: 'query',
            name: 'filter[webhook][contains]',
            required: false,
            schema: { example: 'call.initiated', type: 'string' },
          },
          example: 'call.initiated',
        }),
      'filter[attempts][contains]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only webhook_deliveries whose `attempts` component contains the given text',
            in: 'query',
            name: 'filter[attempts][contains]',
            required: false,
            schema: { example: 'https://fallback.example.com/webhooks', type: 'string' },
          },
          example: 'https://fallback.example.com/webhooks',
        }),
      'filter[started_at][gte]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only webhook_deliveries whose delivery started later than or at given ISO 8601 datetime',
            in: 'query',
            name: 'filter[started_at][gte]',
            required: false,
            schema: { example: '2019-03-29T11:10:00Z', type: 'string' },
          },
          example: '2019-03-29T11:10:00Z',
        }),
      'filter[started_at][lte]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only webhook_deliveries whose delivery started earlier than or at given ISO 8601 datetime',
            in: 'query',
            name: 'filter[started_at][lte]',
            required: false,
            schema: { example: '2019-03-29T11:10:00Z', type: 'string' },
          },
          example: '2019-03-29T11:10:00Z',
        }),
      'filter[finished_at][gte]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only webhook_deliveries whose delivery finished later than or at given ISO 8601 datetime',
            in: 'query',
            name: 'filter[finished_at][gte]',
            required: false,
            schema: { example: '2019-03-29T11:10:00Z', type: 'string' },
          },
          example: '2019-03-29T11:10:00Z',
        }),
      'filter[finished_at][lte]': z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return only webhook_deliveries whose delivery finished earlier than or at given ISO 8601 datetime',
            in: 'query',
            name: 'filter[finished_at][lte]',
            required: false,
            schema: { example: '2019-03-29T11:10:00Z', type: 'string' },
          },
          example: '2019-03-29T11:10:00Z',
        }),
      'page[number]': PageNumberParamsSchema,
      'page[size]': PageSizeParamsSchema,
    }),
  },
  responses: {
    200: ListWebhookDeliveriesResponseResponse,
    401: { description: 'Unauthorized' },
    422: { description: 'Unprocessable entity' },
  },
})

